export function parseSeries(body = '') {
  return body
    .split('\n')
    .map((x) => x.trim())
    .filter(Boolean)
    .map((row) => {
      const match = row.match(/^(.+?)\s*[:：]\s*(\d+(?:\.\d+)?)$/);
      return match ? { label: match[1].trim(), value: Number(match[2]) } : null;
    });
}
